import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"49、【革】 離下兌上","description":"子夏易傳 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"子夏易傳 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/zixia/051.md","filePath":"classics/zixia/051.md"}'),i={name:"classics/zixia/051.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><p>卦辭：革，已日乃孚，元亨利貞，悔亡。</p><p>彖曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之，文明以説，大亨以正。革而當其悔，乃亡天地。革而四時成，湯武革命，順乎天而應乎人。革之時大矣哉。</p><p>子夏：火不遂其上，澤不得而下，故相息息也者，勞而止之而得其自生也。二女同居，志乖而不可處，故革而制之，後乃成也。已日而信之，文明而説之剛，則大中元亨以正也。革而當其悔，乃亡物，不久革之而後成。天地革而成四時也。湯武革命，得其時而天下正也。革非習近之所得也，其大矣哉。</p><p>象曰：澤中有火，革。君子以治厯明時。</p><p>子夏：澤中有火，革而後存。君子修其歴數，明其四時之革，而授以民時也。</p><p>初九，鞏用黃牛之革。</p><p>象曰：鞏用黃牛，不可以有為也。</p><p>子夏：革者，中格事，順於人，而後民志堅，而勉其務也。從已之為而為，則莫聽也，其能久乎，愼初者也。</p><p>六二，已日乃革之，徵吉無咎。</p><p>象曰：已日革之行有嘉也。</p><p>子夏：柔以守位，中以為道，上應於五，有命而行。已日遂革而從其制也。以斯而行，嘉吉也。</p><p>九三，徵兇，貞厲。革言三就，有孚。</p><p>象曰：革言三就，又何之矣。</p><p>子夏：剛得上位，專極其火，性將制，其應不從，其革也。反道背時，徵之兇，正之危。自初至三，令已成矣，民已信，又何雲也。</p><p>九四，悔亡，有孚。改命吉。</p><p>象曰：改命之吉，信志也。</p><p>子夏：剛能辨志，信而行正，守卑上從，承命而改，得其道矣，何悔之有。</p><p>九五，大人虎變，未佔有孚。</p><p>象曰：大人虎變，其文炳也。</p><p>子夏：剛居尊而革之知變之道，勇於變革，易而為功也。得於中而煥乎其外，理著於兆矣，豈俟佔而知哉。</p><p>上六，君子豹變，小人革面。徵兇，居。貞吉。</p><p>象曰：君子豹變，其文蔚也。小人革面，順以從君也。</p><p>子夏：虎變者，明其理，勇於變也。發而成文，君子之類也，大人之道也。其次勇而變焉，故其文蔚也。內信而外説也。小人無所明也。安於舊俗，樂於縱。故革面而已也。猶思其故行也，則周之三監也。徵之兇哉。居而守正，獲其吉也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
